<script setup lang="ts">
const route=useRoute();const token=computed(()=>String(route.params.token||''));const password=ref('');const confirm=ref('');const busy=ref(false);const error=ref('');const valid=ref(false);const complete=ref(false)
useHead({title:'Reset Password'})
onMounted(async()=>{try{await $fetch(`/api/auth/reset-password/${encodeURIComponent(token.value)}`);valid.value=true}catch(e:any){error.value=e?.data?.statusMessage||'This password reset link is invalid or has expired.'}})
async function submit(){busy.value=true;error.value='';try{const csrf=(await $fetch<{csrfToken:string}>('/api/auth/csrf')).csrfToken;await $fetch(`/api/auth/reset-password/${encodeURIComponent(token.value)}`,{method:'POST',body:{password:password.value,confirm_password:confirm.value,csrfToken:csrf}});complete.value=true}catch(e:any){error.value=e?.data?.statusMessage||e?.message||'Password could not be reset.'}finally{busy.value=false}}
</script>
<template><section class="auth-page"><div class="auth-card"><div class="auth-icon">🔐</div><h1>Reset Password</h1><p class="auth-subtitle">Choose a new password for your Lantern account.</p><p v-if="error" class="flash error">{{error}}</p><template v-if="complete"><p class="flash success">Your password has been changed. You can now log in.</p><NuxtLink to="/login" class="button button-gold button-full">Log In</NuxtLink></template><form v-else-if="valid" @submit.prevent="submit"><div class="form-group"><label for="password">New Password</label><input id="password" v-model="password" type="password" placeholder="At least 8 characters" minlength="8" autocomplete="new-password" required></div><div class="form-group"><label for="confirm_password">Confirm Password</label><input id="confirm_password" v-model="confirm" type="password" placeholder="Enter it again" minlength="8" autocomplete="new-password" required></div><button type="submit" class="button button-gold button-full" :disabled="busy">{{busy?'Saving…':'Change Password'}}</button></form></div></section></template>
